import {broomArt} from './spring-art.mjs';
import {itemArt,riverItems,sortedItems,plazaItems,netArt,sprayerArt,seedlingArt,lanternArt,bulbArt,pipeArt,facilityArt,tankArt,binArt,flameArt,riverScene,plazaScene,farmScene,cropDetail,cropSubject,seedPacketArt,wateringCanArt,magnifierArt,smokeArt} from './mission-art.mjs';
import {inspectionTargets,inspectionLocations,inspectionSites} from './mission-content.mjs';
const things=['반납용 컵','종이 안내지','빈 페트병','반납용 음료잔','종이 상자','플라스틱 뚜껑'];
const places=[[15,30],[40,28],[66,35],[20,73],[48,70],[72,76]];
const indices=n=>Array.from({length:n},(_,i)=>i);
const flower=`<span class="flower-art" aria-hidden="true"><i class="flower-stem"></i><i class="flower-leaf"></i><span class="flower-head">${indices(5).map(i=>`<i class="petal" style="--petal:${i}"></i>`).join('')}<i class="flower-center"></i></span></span>`;
const lightSwitch=(on,i,ready)=>`<button data-light="${i}" ${ready?'':'disabled'} aria-label="낮 조명 ${i+1} 끄기" class="day-lamp ${on?'on':'off'}"><span>${bulbArt}</span><b>${on?'켜짐':'꺼짐'}</b></button>`;

export function seasonalBoard(m){
  if(m.kind==='plumb')return `<div class="plumbing-work polished-plumbing ${m.values[0]?'water-running':''}"><div class="pipe-network"><svg class="network-links" viewBox="0 0 600 240" preserveAspectRatio="none" aria-hidden="true"><path d="M79 74H132M204 74H270M364 167H522" stroke="#50716c" stroke-width="20" fill="none"/><path d="M79 74H132M204 74H270M364 167H522" stroke="#c0cfc0" stroke-width="11" fill="none"/></svg><div class="network-node source">${facilityArt}<strong>작업장</strong></div>${indices(3).map(i=>`<button class="pipe-socket ${m.marks[i]?'fitted':''}" data-fit="${i}" aria-label="${['직선','아래로 꺾인','위로 꺾인'][i]} 배관 자리">${pipeArt(i,!m.marks[i])}</button>`).join('')}<div class="network-node destination">${tankArt}<strong>처리 시설</strong></div>${m.values[0]?'<span class="network-flow">물이 처리 시설로 흘러요</span>':''}</div><div class="pipe-controls"><div class="pipe-supplies">${[2,0,1].map(i=>`<button class="loose-pipe ${m.marks[i]?'stored':''} ${m.picked===i?'carrying':''}" data-pipe="${i}" aria-label="${['직선','아래로 꺾인','위로 꺾인'][i]} 배관 집기">${pipeArt(i)}</button>`).join('')}</div><button class="valve" id="water-valve" ${m.marks.slice(0,3).every(Boolean)?'':'disabled'}><i aria-hidden="true"></i>${m.values[0]?'물 흐름 확인':'밸브 열기'}</button></div></div>`;
  if(m.kind==='haul')return `<div class="mission-field natural-river" id="mission-field">${riverScene}${places.map(([x,y],i)=>`<button class="floating-object ${m.marks[i]?'removed':''} ${m.picked===i?'carrying':''}" data-carry="${i}" style="left:${x}%;top:${y}%" aria-label="쓰레기 ${i+1} 집기">${itemArt[riverItems[i]]}</button>`).join('')}<button class="haul-target natural-bin" data-target="load" aria-label="집은 쓰레기를 수거통에 넣기">${binArt('bottle')}<strong>수거통</strong><small>${m.marks.slice(0,6).filter(Boolean).length}/6</small></button><div class="net-tool">${netArt}</div><span class="scene-caption">물 위의 쓰레기를 뜰채로 건져요</span></div>`;
  if(m.kind==='scrub')return `<div class="mission-field plaza-cleanup" id="mission-field">${plazaScene}${places.map(([x,y],i)=>`<button class="ground-object ${m.marks[i]>=4?'removed':''}" data-brush="${i}" style="left:${x}%;top:${y}%;--swept:${m.marks[i]}" aria-label="${plazaItems[i]==='stain'?'바닥 얼룩':plazaItems[i]==='paper'?'종이 조각':'버려진 음료잔'} ${i+1} 치우기">${itemArt[plazaItems[i]]}</button>`).join('')}<div class="brush-cursor real-broom" id="brush-cursor">${broomArt}</div><span class="scene-caption">축제가 끝난 마을 광장</span></div>`;
  if(m.kind==='plant'){
    const watered=m.marks.slice(0,6).every(Boolean);
    return `<div class="planting-work garden-work"><div class="plant-tool">${watered?wateringCanArt:seedPacketArt}${watered?'물뿌리개 · 심은 곳에 두 번씩 물 주기':'씨앗 주머니 · 흙밭 여섯 곳에 심기'}</div><div class="garden-bed" id="mission-field">${farmScene}${[[18,31],[50,31],[82,31],[18,76],[50,76],[82,76]].map(([x,y],i)=>`<button data-brush="${i}" class="soil-pot ${m.marks[i]?'seeded':''} ${m.water[i]>=2?'watered':''} ${m.water[i]?'watering':''} ${m.activePlot===i?'recent-plot':''}" style="left:${x}%;top:${y}%" aria-label="꽃밭 ${i+1} ${watered?'물 주기':'씨앗 심기'}"><i class="seed-grains">· · ·</i><i class="water-drops"></i><span class="growing-flower">${m.water[i]>=2?flower:m.marks[i]?seedlingArt:'<i class="soil-dimple"></i>'}</span><small>${m.water[i]>=2?'꽃이 피었어요':m.marks[i]?watered?`물 ${m.water[i]}/2`:'심었어요':'심을 곳'}</small></button>`).join('')}</div></div>`;
  }
  if(m.kind==='spray')return `<div class="spraying-work planted-farm" id="mission-field">${farmScene}<div class="crop-bed">${m.marks.map((v,i)=>`<button class="spray-crop ${v>=3?'sprayed':''}" data-brush="${i}" aria-label="밭 ${i+1} 농약 뿌리기">${seedlingArt}<i style="opacity:${v/4}"></i>${v>=3?'<b>✓</b>':''}</button>`).join('')}</div><div class="sprayer-cursor real-sprayer" id="brush-cursor">${sprayerArt}<i class="mist"></i></div></div>`;
  if(m.kind==='inspect'){
    const photo=m.id==='wait',sites=inspectionSites(m),locations=inspectionLocations(m),targets=inspectionTargets(m),site=sites[m.focus];
    return `<div class="observation-work natural-observation ${photo?'camera-work':''}"><div class="mission-field ${photo?'real-photo-field':'crop-observation-field'}" id="mission-field">${photo?'':farmScene}${sites.map((s,i)=>`<button class="${photo?'photo-zone':'crop-subject'} ${m.marks[i]?'recorded':''} ${m.focus===i?'in-focus':''}" data-observe="${i}" style="left:${locations[i][0]}%;top:${locations[i][1]}%" aria-label="${s.name} ${photo?'카메라 맞추기':'확대 관찰'}" aria-pressed="${m.focus===i}">${photo?'<i class="viewfinder-corners"></i>':seedlingArt}<small>${photo?'관찰 '+(i+1):i+1}</small>${m.marks[i]?'<b>✓</b>':''}</button>`).join('')}<div class="inspection-cursor ${photo?'camera-cursor':''}" id="inspection-cursor" style="left:85%;top:37%"></div><div class="camera-flash"></div></div><div class="observation-console polished-console"><span id="focus-name" aria-live="polite">${site?site.description:photo?'카메라를 세 구역에 맞춰 사진을 남겨요.':'돋보기를 잎에 갖다 대어 상태를 살펴보세요.'}</span>${photo?'<button id="record-observation">사진 찍기</button>':`<div class="damage-selections">${Array.from({length:6},(_,i)=>`<button data-crop-select="${i}" ${m.seen[i]?'':'disabled'} aria-label="${i+1}번 피해 구역 선택" aria-pressed="${!!m.marks[i]}">${i+1}</button>`).join('')}<button id="submit-damage" ${m.marks.slice(0,6).filter(Boolean).length===3?'':'disabled'}>제출</button></div>`}</div></div>`;
  }
  if(m.kind==='sort')return `<div class="sorting-work natural-sorting"><div class="sorting-table"><div class="sorting-items">${things.map((name,i)=>`<button class="sort-item ${m.marks[i]?'stored':''} ${m.picked===i?'carrying':''}" data-carry="${i}" aria-label="${name}">${itemArt[sortedItems[i]]}<small>${name}</small></button>`).join('')}</div></div><div class="sorting-bins">${[['cup','cup','컵 반납함'],['paper','paper','종이함'],['plastic','bottle','플라스틱함']].map(([id,icon,name])=>`<button class="mission-bin bin-${id}" data-target="${id}">${binArt(icon)}<strong>${name}</strong></button>`).join('')}</div><div class="day-lights ${m.marks.slice(0,6).every(Boolean)?'':'waiting'}"><span>분류 후 낮 조명을 꺼요</span>${m.lights.map((on,i)=>lightSwitch(on,i,m.marks.slice(0,6).every(Boolean))).join('')}</div></div>`;
  if(m.kind==='memory')return `<div class="lamp-work hanging-lanterns"><div class="lamp-wire"></div><div class="mission-lamps">${['주황','파랑','초록'].map((color,i)=>`<button class="mission-lamp lamp-${i}" data-lamp="${i}" aria-label="${color} 등 스위치">${lanternArt}<strong>${color}</strong></button>`).join('')}</div><div class="memory-track">${m.done?'두 번의 점검 완료':`점검 ${m.round+1}/2 · <span id="memory-index">${m.index}/${m.round===0?3:4}</span>`}</div><button class="preview-sequence" id="preview-sequence">순서 다시 보기</button></div>`;
  if(m.kind==='tune')return `<div class="coin-budget"><div class="budget-coins">${indices(9).map(i=>`<button class="budget-coin ${m.marks[i]?'stored':''} ${m.picked===i?'carrying':''}" data-carry="${i}" aria-label="동전 ${i+1} 집기"><svg viewBox="0 0 60 60" aria-hidden="true"><circle cx="30" cy="30" r="26" fill="#e5b653" stroke="#8c602b" stroke-width="4"/><circle cx="30" cy="30" r="19" fill="none" stroke="#fff0b1" stroke-width="2"/><path d="M30 14v32M21 20h14q10 0 0 10h-10q-10 0 0 10h14" fill="none" stroke="#8c602b" stroke-width="3"/></svg></button>`).join('')}</div><div class="budget-pouches">${['처리 시설','하천 청소','물가 꾸미기'].map((name,i)=>`<button class="budget-pouch ${m.values[i]===3?'filled':''}" data-target="${i}" aria-label="${name} 주머니에 동전 넣기"><svg viewBox="0 0 160 140" aria-hidden="true"><path d="M52 14q28 10 56 0l-8 30q43 27 36 70q-6 29-56 23q-50 6-56-23q-7-43 36-70z" fill="${['#7a9970','#709ba2','#c0a167'][i]}" stroke="#574e38" stroke-width="4"/><path d="M58 40q22 6 44 0" stroke="#dcc89c" stroke-width="7" fill="none"/></svg><strong>${name}</strong><span>${m.values[i]} / 3</span></button>`).join('')}</div></div>`;
  if(m.kind==='stack')return m.cups<5?`<div class="cup-catch-work"><div class="cup-catch-field" id="cup-catch-field">${plazaScene}<span class="paper-cup falling-catch-cup" id="falling-cup" hidden></span><div class="catching-tray" id="catching-tray" role="slider" tabindex="0" aria-label="컵 받침 좌우 이동" aria-valuemin="12" aria-valuemax="88" aria-valuenow="${Math.round(m.catcherX)}" style="left:${m.catcherX}%">${indices(m.cups).map(i=>`<span class="paper-cup caught-cup" style="--cup:${i}"></span>`).join('')}<div class="wooden-tray"></div></div><span class="cup-count">받은 컵 ${m.cups} / 5</span></div></div>`:`<div class="fairy-light-stage"><div class="fairy-sky"></div><p>낮에 켜져 있는 꼬마전구를 꺼 주세요.</p><div class="fairy-strings">${m.lights.map((on,i)=>`<button class="fairy-string ${on?'is-on':'is-off'}" data-switch="${i}" aria-label="꼬마전구 줄 ${i+1} 끄기" aria-pressed="${!on}"><svg viewBox="0 0 600 75" aria-hidden="true"><path d="M0 8Q300 66 600 8" fill="none" stroke="#4c604d" stroke-width="3"/>${Array.from({length:9},(_,j)=>{const x=35+j*66,y=8+50*(x/600)*(1-x/600);return `<path d="M${x} ${y}v12" stroke="#4c604d" stroke-width="3"/><ellipse class="fairy-bulb" cx="${x}" cy="${y+21}" rx="8" ry="12"/>`;}).join('')}</svg><span>${on?'스위치 끄기':'꺼졌어요 ✓'}</span></button>`).join('')}</div></div>`;
  if(m.kind==='ignite')return `<div class="friction-work ${m.heat>=100?'burning':''}"><div class="burn-scene">${plazaScene}<div class="burn-pile">${['box','paper','bag'].map(id=>itemArt[id]).join('')}</div><div class="burn-fire">${flameArt}</div><div class="observed-smoke">${smokeArt}<i></i><i></i><i></i></div><span class="scene-caption">${m.heat>=100?'쓰레기가 연기와 재로 바뀌었어요.':'손잡이를 좌우로 문질러요.'}</span></div><button class="friction-handle" id="friction-handle" aria-label="마찰 도구 손잡이 좌우로 문지르기"><span>↔</span>손잡이를 잡고 좌우로 문질러요</button><div class="friction-heat" role="progressbar" aria-label="마찰열" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${m.heat}"><span style="width:${m.heat}%"></span></div></div>`;
  throw new Error('Unknown seasonal board: '+m.kind);
}
